**Plan**
- A MonoBehaviour that adds a UIDocument (with runtime PanelSettings) and builds the menu in code with new Button() and new Label().
- Play loads the game scene; Continue is disabled unless a save flag exists in PlayerPrefs; Quit exits the application.
- Settings swaps the menu for a small panel with a Back button, all in the same root.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

public class MainMenuUI : MonoBehaviour
{
    [SerializeField] private string gameSceneName = "Game";
    [SerializeField] private string saveKey = "HasSave";

    private VisualElement root;
    private VisualElement menuPanel;
    private VisualElement settingsPanel;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        root.style.backgroundColor = new Color(0.07f, 0.08f, 0.12f, 1f);

        menuPanel = BuildMenu();
        settingsPanel = BuildSettingsPanel();
        settingsPanel.style.display = DisplayStyle.None;
        root.Add(menuPanel);
        root.Add(settingsPanel);
    }

    private VisualElement BuildMenu()
    {
        VisualElement panel = new VisualElement();
        panel.style.alignItems = Align.Center;

        Label title = new Label("SHADOW RUNNER");
        title.style.fontSize = 72;
        title.style.unityFontStyleAndWeight = FontStyle.Bold;
        title.style.color = Color.white;
        title.style.marginBottom = 50;
        panel.Add(title);

        panel.Add(MakeButton("Play", OnPlay));

        Button continueButton = MakeButton("Continue", OnContinue);
        bool hasSave = PlayerPrefs.GetInt(saveKey, 0) == 1;
        continueButton.SetEnabled(hasSave);
        continueButton.style.opacity = hasSave ? 1f : 0.4f;
        panel.Add(continueButton);

        panel.Add(MakeButton("Settings", () => ShowSettings(true)));
        panel.Add(MakeButton("Quit", OnQuit));
        return panel;
    }

    private VisualElement BuildSettingsPanel()
    {
        VisualElement panel = new VisualElement();
        panel.style.alignItems = Align.Center;

        Label header = new Label("Settings");
        header.style.fontSize = 56;
        header.style.color = Color.white;
        header.style.marginBottom = 30;
        panel.Add(header);

        Toggle muteToggle = new Toggle("Mute audio");
        muteToggle.value = AudioListener.pause;
        muteToggle.style.color = Color.white;
        muteToggle.style.fontSize = 28;
        muteToggle.RegisterValueChangedCallback(evt => AudioListener.pause = evt.newValue);
        panel.Add(muteToggle);

        panel.Add(MakeButton("Back", () => ShowSettings(false)));
        return panel;
    }

    private Button MakeButton(string text, Action onClick)
    {
        Button button = new Button(onClick);
        button.text = text;
        button.style.width = 360;
        button.style.height = 70;
        button.style.fontSize = 30;
        button.style.marginBottom = 14;
        button.style.color = Color.white;
        button.style.backgroundColor = new Color(0.2f, 0.35f, 0.75f, 1f);
        button.style.borderTopLeftRadius = 10;
        button.style.borderTopRightRadius = 10;
        button.style.borderBottomLeftRadius = 10;
        button.style.borderBottomRightRadius = 10;
        return button;
    }

    private void ShowSettings(bool show)
    {
        menuPanel.style.display = show ? DisplayStyle.None : DisplayStyle.Flex;
        settingsPanel.style.display = show ? DisplayStyle.Flex : DisplayStyle.None;
    }

    private void OnPlay()
    {
        PlayerPrefs.SetInt(saveKey, 1);
        PlayerPrefs.Save();
        SceneManager.LoadScene(gameSceneName);
    }

    private void OnContinue()
    {
        SceneManager.LoadScene(gameSceneName);
    }

    private void OnQuit()
    {
        Application.Quit();
    }
}
```

Attach MainMenuUI to an empty GameObject and set the game scene name; the component creates its own UIDocument and PanelSettings at runtime. Continue is created disabled and dimmed unless the PlayerPrefs "HasSave" flag is 1, which Play sets. Settings and the main menu are two panels in the same root that are toggled with display styles.

**Plan**
- Build a settings panel in code with two Slider controls (master volume, mouse sensitivity) and a Toggle (fullscreen).
- Load stored values from PlayerPrefs on enable and apply them immediately (AudioListener.volume, Screen.fullScreen).
- Save on every change and expose the sensitivity through a public static property so other scripts can read it.

```csharp
using System;
using UnityEngine;
using UnityEngine.UIElements;

public class SettingsMenuUI : MonoBehaviour
{
    private const string VolumeKey = "Settings.MasterVolume";
    private const string SensitivityKey = "Settings.MouseSensitivity";
    private const string FullscreenKey = "Settings.Fullscreen";

    public static float MouseSensitivity { get; private set; } = 2f;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        float volume = PlayerPrefs.GetFloat(VolumeKey, 1f);
        float sensitivity = PlayerPrefs.GetFloat(SensitivityKey, 2f);
        bool fullscreen = PlayerPrefs.GetInt(FullscreenKey, Screen.fullScreen ? 1 : 0) == 1;
        ApplyVolume(volume);
        MouseSensitivity = sensitivity;
        Screen.fullScreen = fullscreen;

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        root.style.backgroundColor = new Color(0.08f, 0.09f, 0.13f, 1f);

        VisualElement card = new VisualElement();
        card.style.width = 640;
        card.style.paddingTop = 30;
        card.style.paddingBottom = 30;
        card.style.paddingLeft = 40;
        card.style.paddingRight = 40;
        card.style.backgroundColor = new Color(0.14f, 0.16f, 0.22f, 1f);
        card.style.borderTopLeftRadius = 16;
        card.style.borderTopRightRadius = 16;
        card.style.borderBottomLeftRadius = 16;
        card.style.borderBottomRightRadius = 16;
        root.Add(card);

        Label title = new Label("Settings");
        title.style.fontSize = 48;
        title.style.color = Color.white;
        title.style.marginBottom = 24;
        card.Add(title);

        Slider volumeSlider = MakeSlider(card, "Master Volume", 0f, 1f, volume, value =>
        {
            ApplyVolume(value);
            PlayerPrefs.SetFloat(VolumeKey, value);
            PlayerPrefs.Save();
        });
        volumeSlider.name = "VolumeSlider";

        MakeSlider(card, "Mouse Sensitivity", 0.1f, 10f, sensitivity, value =>
        {
            MouseSensitivity = value;
            PlayerPrefs.SetFloat(SensitivityKey, value);
            PlayerPrefs.Save();
        });

        Toggle fullscreenToggle = new Toggle("Fullscreen");
        fullscreenToggle.value = fullscreen;
        fullscreenToggle.style.fontSize = 26;
        fullscreenToggle.style.color = Color.white;
        fullscreenToggle.RegisterValueChangedCallback(evt =>
        {
            Screen.fullScreen = evt.newValue;
            PlayerPrefs.SetInt(FullscreenKey, evt.newValue ? 1 : 0);
            PlayerPrefs.Save();
        });
        card.Add(fullscreenToggle);
    }

    private static Slider MakeSlider(VisualElement parent, string labelText, float min, float max, float start, Action<float> onChange)
    {
        Label label = new Label(labelText + ": " + start.ToString("0.00"));
        label.style.fontSize = 26;
        label.style.color = Color.white;
        label.style.marginTop = 10;
        parent.Add(label);

        Slider slider = new Slider(min, max);
        slider.value = start;
        slider.style.marginBottom = 16;
        slider.RegisterValueChangedCallback(evt =>
        {
            label.text = labelText + ": " + evt.newValue.ToString("0.00");
            onChange(evt.newValue);
        });
        parent.Add(slider);
        return slider;
    }

    private static void ApplyVolume(float value)
    {
        AudioListener.volume = Mathf.Clamp01(value);
    }
}
```

Each slider is created by a helper that updates its own label, calls the supplied callback, and the callbacks write to PlayerPrefs and apply the setting immediately. On enable the saved values are read back and applied before the UI is built, so the controls start at the stored positions. Other scripts can read `SettingsMenuUI.MouseSensitivity` for their look code.

**Plan**
- Build a hidden overlay with Resume, Restart Level and Quit to Menu buttons in code using UI Toolkit.
- Toggle the pause state when Escape is pressed (Resume button does the same), setting Time.timeScale to 0 or back to 1.
- Restart reloads the active scene and Quit loads the menu scene; both restore time first.

```csharp
using System;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

public class PauseMenuUI : MonoBehaviour
{
    [SerializeField] private string menuSceneName = "MainMenu";

    private VisualElement overlay;
    private bool paused;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        overlay = new VisualElement();
        overlay.style.position = Position.Absolute;
        overlay.style.left = 0;
        overlay.style.right = 0;
        overlay.style.top = 0;
        overlay.style.bottom = 0;
        overlay.style.alignItems = Align.Center;
        overlay.style.justifyContent = Justify.Center;
        overlay.style.backgroundColor = new Color(0f, 0f, 0f, 0.7f);
        overlay.style.display = DisplayStyle.None;
        root.Add(overlay);

        Label title = new Label("PAUSED");
        title.style.fontSize = 72;
        title.style.color = Color.white;
        title.style.marginBottom = 40;
        overlay.Add(title);

        overlay.Add(MakeButton("Resume", () => SetPaused(false)));
        overlay.Add(MakeButton("Restart Level", RestartLevel));
        overlay.Add(MakeButton("Quit to Menu", QuitToMenu));
    }

    private void OnDisable()
    {
        Time.timeScale = 1f;
        paused = false;
    }

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.Escape))
        {
            SetPaused(!paused);
        }
    }

    private void SetPaused(bool value)
    {
        paused = value;
        Time.timeScale = value ? 0f : 1f;
        overlay.style.display = value ? DisplayStyle.Flex : DisplayStyle.None;
    }

    private void RestartLevel()
    {
        Time.timeScale = 1f;
        SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
    }

    private void QuitToMenu()
    {
        Time.timeScale = 1f;
        SceneManager.LoadScene(menuSceneName);
    }

    private static Button MakeButton(string text, Action onClick)
    {
        Button button = new Button(onClick);
        button.text = text;
        button.style.width = 360;
        button.style.height = 64;
        button.style.fontSize = 28;
        button.style.marginBottom = 14;
        button.style.color = Color.white;
        button.style.backgroundColor = new Color(0.2f, 0.3f, 0.6f, 1f);
        return button;
    }
}
```

The overlay is a full-screen absolute element toggled with its display style, and the same SetPaused method is used by Escape and the Resume button so they cannot get out of sync. Input and button clicks keep working while paused because UI Toolkit and the legacy Input use unscaled time. Restart and Quit reset Time.timeScale to 1 before changing scene so the next scene does not start frozen.

**Plan**
- Define a serializable LevelEntry (display name and scene name) and expose a list in the inspector.
- Read the unlocked level count from PlayerPrefs and build one button per level inside a ScrollView.
- Locked levels get a lock marker and are disabled; unlocked ones load their scene on click.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

[Serializable]
public class LevelEntry
{
    public string displayName = "Level";
    public string sceneName = "Level1";
}

public class LevelSelectUI : MonoBehaviour
{
    public const string UnlockedKey = "UnlockedLevels";

    [SerializeField] private List<LevelEntry> levels = new List<LevelEntry>
    {
        new LevelEntry { displayName = "Level 1", sceneName = "Level1" },
        new LevelEntry { displayName = "Level 2", sceneName = "Level2" },
        new LevelEntry { displayName = "Level 3", sceneName = "Level3" },
    };

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.paddingTop = 60;
        root.style.backgroundColor = new Color(0.07f, 0.09f, 0.13f, 1f);

        Label title = new Label("Select Level");
        title.style.fontSize = 60;
        title.style.color = Color.white;
        title.style.marginBottom = 30;
        root.Add(title);

        ScrollView list = new ScrollView();
        list.style.width = 520;
        list.style.flexGrow = 1;
        root.Add(list);

        int unlocked = Mathf.Max(1, PlayerPrefs.GetInt(UnlockedKey, 1));
        for (int i = 0; i < levels.Count; i++)
        {
            list.Add(BuildLevelButton(levels[i], i < unlocked));
        }
    }

    private Button BuildLevelButton(LevelEntry entry, bool isUnlocked)
    {
        string sceneName = entry.sceneName;
        Button button = new Button(() => SceneManager.LoadScene(sceneName));
        button.text = isUnlocked ? entry.displayName : entry.displayName + "   [LOCKED]";
        button.style.height = 70;
        button.style.fontSize = 30;
        button.style.marginBottom = 12;
        button.style.color = isUnlocked ? Color.white : new Color(0.6f, 0.6f, 0.6f, 1f);
        button.style.backgroundColor = isUnlocked
            ? new Color(0.2f, 0.45f, 0.8f, 1f)
            : new Color(0.2f, 0.2f, 0.25f, 1f);
        button.SetEnabled(isUnlocked);
        return button;
    }

    public static void UnlockUpTo(int levelCount)
    {
        int current = PlayerPrefs.GetInt(UnlockedKey, 1);
        if (levelCount > current)
        {
            PlayerPrefs.SetInt(UnlockedKey, levelCount);
            PlayerPrefs.Save();
        }
    }
}
```

The list of levels is edited in the inspector; the menu creates one button per entry and compares its index to the unlocked count stored in PlayerPrefs. Locked buttons are disabled, greyed and labelled. `LevelSelectUI.UnlockUpTo(n)` is a static helper a level-complete script can call to raise the unlocked count.

**Plan**
- Build a loading screen with a title, a progress bar and a percentage Label.
- Start SceneManager.LoadSceneAsync for the next scene with allowSceneActivation off, and map its 0-0.9 progress to 0-100%.
- Update the bar and label each frame, then activate the scene once the load reaches 100%.

```csharp
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

public class LoadingScreenUI : MonoBehaviour
{
    [SerializeField] private string sceneToLoad = "";
    [SerializeField] private float minimumShowTime = 0.75f;

    private Label percentLabel;
    private VisualElement barFill;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        root.style.backgroundColor = new Color(0.05f, 0.06f, 0.09f, 1f);

        Label title = new Label("Loading...");
        title.style.fontSize = 56;
        title.style.color = Color.white;
        title.style.marginBottom = 30;
        root.Add(title);

        VisualElement bar = new VisualElement();
        bar.style.width = 700;
        bar.style.height = 28;
        bar.style.backgroundColor = new Color(0.2f, 0.22f, 0.3f, 1f);
        bar.style.borderTopLeftRadius = 14;
        bar.style.borderTopRightRadius = 14;
        bar.style.borderBottomLeftRadius = 14;
        bar.style.borderBottomRightRadius = 14;
        root.Add(bar);

        barFill = new VisualElement();
        barFill.style.height = Length.Percent(100);
        barFill.style.width = Length.Percent(0);
        barFill.style.backgroundColor = new Color(0.3f, 0.8f, 0.45f, 1f);
        barFill.style.borderTopLeftRadius = 14;
        barFill.style.borderBottomLeftRadius = 14;
        bar.Add(barFill);

        percentLabel = new Label("0%");
        percentLabel.style.fontSize = 32;
        percentLabel.style.color = Color.white;
        percentLabel.style.marginTop = 16;
        root.Add(percentLabel);

        StartCoroutine(LoadRoutine());
    }

    private IEnumerator LoadRoutine()
    {
        AsyncOperation operation;
        if (string.IsNullOrEmpty(sceneToLoad))
        {
            int next = (SceneManager.GetActiveScene().buildIndex + 1) % SceneManager.sceneCountInBuildSettings;
            operation = SceneManager.LoadSceneAsync(next);
        }
        else
        {
            operation = SceneManager.LoadSceneAsync(sceneToLoad);
        }
        operation.allowSceneActivation = false;

        float shown = 0f;
        float elapsed = 0f;
        while (shown < 1f || elapsed < minimumShowTime)
        {
            elapsed += Time.unscaledDeltaTime;
            float target = Mathf.Clamp01(operation.progress / 0.9f);
            shown = Mathf.MoveTowards(shown, target, Time.unscaledDeltaTime * 1.5f);
            barFill.style.width = Length.Percent(shown * 100f);
            percentLabel.text = Mathf.RoundToInt(shown * 100f) + "%";
            yield return null;
        }

        operation.allowSceneActivation = true;
    }
}
```

Unity reports async progress only up to 0.9 while activation is held back, so the script divides by 0.9 to get a true 0–100% value. The displayed value moves smoothly toward that target and the loop waits for a minimum show time, so the bar never flickers. When it reaches 100% the scene is activated. Leave the scene name empty to load the next build index.

**Plan**
- Build a hidden overlay with a "GAME OVER" title, score labels, and Retry and Main Menu buttons.
- Public Show(score) saves the best score in PlayerPrefs, fills the labels and fades the overlay in with a coroutine on unscaled time.
- Retry reloads the active scene and Main Menu loads the menu scene, both resetting time scale.

```csharp
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

public class GameOverScreenUI : MonoBehaviour
{
    private const string BestScoreKey = "BestScore";

    [SerializeField] private string menuSceneName = "MainMenu";
    [SerializeField] private float fadeDuration = 1.0f;

    private VisualElement overlay;
    private Label scoreLabel;
    private Label bestLabel;
    private Coroutine fadeRoutine;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        overlay = new VisualElement();
        overlay.style.position = Position.Absolute;
        overlay.style.left = 0;
        overlay.style.right = 0;
        overlay.style.top = 0;
        overlay.style.bottom = 0;
        overlay.style.alignItems = Align.Center;
        overlay.style.justifyContent = Justify.Center;
        overlay.style.backgroundColor = new Color(0.05f, 0f, 0f, 0.85f);
        overlay.style.opacity = 0f;
        overlay.style.display = DisplayStyle.None;
        root.Add(overlay);

        Label title = new Label("GAME OVER");
        title.style.fontSize = 88;
        title.style.color = new Color(0.9f, 0.2f, 0.2f, 1f);
        title.style.marginBottom = 30;
        overlay.Add(title);

        scoreLabel = new Label("Score: 0");
        scoreLabel.style.fontSize = 44;
        scoreLabel.style.color = Color.white;
        overlay.Add(scoreLabel);

        bestLabel = new Label("Best: 0");
        bestLabel.style.fontSize = 34;
        bestLabel.style.color = new Color(1f, 0.85f, 0.3f, 1f);
        bestLabel.style.marginBottom = 40;
        overlay.Add(bestLabel);

        Button retry = new Button(() =>
        {
            Time.timeScale = 1f;
            SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
        });
        retry.text = "Retry";
        StyleButton(retry);
        overlay.Add(retry);

        Button menu = new Button(() =>
        {
            Time.timeScale = 1f;
            SceneManager.LoadScene(menuSceneName);
        });
        menu.text = "Main Menu";
        StyleButton(menu);
        overlay.Add(menu);
    }

    public void Show(int finalScore)
    {
        int best = PlayerPrefs.GetInt(BestScoreKey, 0);
        if (finalScore > best)
        {
            best = finalScore;
            PlayerPrefs.SetInt(BestScoreKey, best);
            PlayerPrefs.Save();
        }

        scoreLabel.text = "Score: " + finalScore;
        bestLabel.text = "Best: " + best;
        overlay.style.display = DisplayStyle.Flex;
        if (fadeRoutine != null) StopCoroutine(fadeRoutine);
        fadeRoutine = StartCoroutine(FadeIn());
    }

    private IEnumerator FadeIn()
    {
        float t = 0f;
        while (t < fadeDuration)
        {
            t += Time.unscaledDeltaTime;
            overlay.style.opacity = Mathf.Clamp01(t / fadeDuration);
            yield return null;
        }
        overlay.style.opacity = 1f;
    }

    private static void StyleButton(Button button)
    {
        button.style.width = 320;
        button.style.height = 64;
        button.style.fontSize = 28;
        button.style.marginBottom = 14;
        button.style.color = Color.white;
        button.style.backgroundColor = new Color(0.25f, 0.3f, 0.5f, 1f);
    }
}
```

Another script calls `GetComponent<GameOverScreenUI>().Show(score)` when the player dies. Show updates the saved best score, reveals the overlay and fades its opacity from 0 to 1 using unscaled time so it still works if the game was frozen. Retry and Main Menu both reset Time.timeScale before changing scene.

**Plan**
- A ConfirmDialog MonoBehaviour that builds a hidden modal (dim backdrop, message, Yes and No buttons) in code.
- A static Instance property finds or creates the dialog, so any script can call ConfirmDialog.Instance.Show(message, onYes, onNo).
- Clicking either button hides the dialog and then invokes the matching callback exactly once.

```csharp
using System;
using UnityEngine;
using UnityEngine.UIElements;

public class ConfirmDialog : MonoBehaviour
{
    private static ConfirmDialog instance;

    public static ConfirmDialog Instance
    {
        get
        {
            if (instance == null)
            {
                instance = FindObjectOfType<ConfirmDialog>();
                if (instance == null)
                {
                    GameObject go = new GameObject("ConfirmDialog");
                    instance = go.AddComponent<ConfirmDialog>();
                }
            }
            return instance;
        }
    }

    private VisualElement backdrop;
    private Label messageLabel;
    private Action yesCallback;
    private Action noCallback;

    private void Awake()
    {
        if (instance != null && instance != this)
        {
            Destroy(gameObject);
            return;
        }
        instance = this;
        Build();
    }

    private void Build()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            settings.sortingOrder = 100;
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        backdrop = new VisualElement();
        backdrop.style.position = Position.Absolute;
        backdrop.style.left = 0;
        backdrop.style.right = 0;
        backdrop.style.top = 0;
        backdrop.style.bottom = 0;
        backdrop.style.alignItems = Align.Center;
        backdrop.style.justifyContent = Justify.Center;
        backdrop.style.backgroundColor = new Color(0f, 0f, 0f, 0.6f);
        backdrop.style.display = DisplayStyle.None;
        root.Add(backdrop);

