- Define a Health component with current/max values and an `OnChanged(current, max)` event raised by TakeDamage and Heal.
- A HealthBarUI builds a UI Toolkit bar, subscribes to the Health event and stores the target fraction.
- Every frame the displayed fraction lerps toward the target and sets the fill width in percent; the colour turns red when low.

```csharp
using System;
using UnityEngine;
using UnityEngine.UIElements;

public class Health : MonoBehaviour
{
    [SerializeField] private float maxHealth = 100f;
    private float current;

    public event Action<float, float> OnChanged;

    public float Current { get { return current; } }
    public float Max { get { return maxHealth; } }

    private void Awake()
    {
        current = maxHealth;
    }

    public void TakeDamage(float amount)
    {
        if (amount <= 0f) return;
        current = Mathf.Max(0f, current - amount);
        RaiseChanged();
    }

    public void Heal(float amount)
    {
        if (amount <= 0f) return;
        current = Mathf.Min(maxHealth, current + amount);
        RaiseChanged();
    }

    public void RaiseChanged()
    {
        if (OnChanged != null) OnChanged(current, maxHealth);
    }
}

public class HealthBarUI : MonoBehaviour
{
    [SerializeField] private Health target;
    [SerializeField] private float smoothing = 8f;
    [SerializeField] private KeyCode debugDamageKey = KeyCode.H;
    [SerializeField] private KeyCode debugHealKey = KeyCode.J;

    private VisualElement fill;
    private Label valueLabel;
    private float targetFraction = 1f;
    private float displayedFraction = 1f;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        VisualElement frame = new VisualElement();
        frame.style.position = Position.Absolute;
        frame.style.left = 40;
        frame.style.bottom = 40;
        frame.style.width = 460;
        frame.style.height = 36;
        frame.style.backgroundColor = new Color(0.1f, 0.1f, 0.12f, 0.85f);
        frame.style.borderTopLeftRadius = 8;
        frame.style.borderTopRightRadius = 8;
        frame.style.borderBottomLeftRadius = 8;
        frame.style.borderBottomRightRadius = 8;
        frame.style.overflow = Overflow.Hidden;
        root.Add(frame);

        fill = new VisualElement();
        fill.style.height = Length.Percent(100);
        fill.style.width = Length.Percent(100);
        fill.style.backgroundColor = new Color(0.25f, 0.8f, 0.35f, 1f);
        frame.Add(fill);

        valueLabel = new Label();
        valueLabel.style.position = Position.Absolute;
        valueLabel.style.left = 0;
        valueLabel.style.right = 0;
        valueLabel.style.unityTextAlign = TextAnchor.MiddleCenter;
        valueLabel.style.fontSize = 20;
        valueLabel.style.color = Color.white;
        frame.Add(valueLabel);

        if (target != null)
        {
            target.OnChanged += HandleChanged;
            HandleChanged(target.Current, target.Max);
            displayedFraction = targetFraction;
            ApplyFill();
        }
    }

    private void OnDisable()
    {
        if (target != null) target.OnChanged -= HandleChanged;
    }

    private void HandleChanged(float current, float max)
    {
        targetFraction = max > 0f ? Mathf.Clamp01(current / max) : 0f;
        valueLabel.text = Mathf.CeilToInt(current) + " / " + Mathf.CeilToInt(max);
    }

    private void Update()
    {
        if (target != null)
        {
            if (Input.GetKeyDown(debugDamageKey)) target.TakeDamage(15f);
            if (Input.GetKeyDown(debugHealKey)) target.Heal(10f);
        }

        float t = 1f - Mathf.Exp(-smoothing * Time.deltaTime);
        displayedFraction = Mathf.Lerp(displayedFraction, targetFraction, t);
        ApplyFill();
    }

    private void ApplyFill()
    {
        fill.style.width = Length.Percent(displayedFraction * 100f);
        fill.style.backgroundColor = displayedFraction < 0.25f
            ? new Color(0.9f, 0.2f, 0.2f, 1f)
            : new Color(0.25f, 0.8f, 0.35f, 1f);
    }
}
```

Assign the Health component to HealthBarUI in the inspector; the bar subscribes in OnEnable and unsubscribes in OnDisable so it never leaks handlers. The event only updates the target fraction, and Update eases the displayed width toward it with a frame-rate independent lerp, so damage and healing slide smoothly. H and J apply test damage and healing so you can try it without other scripts.

**Plan**
- Build a centre-screen crosshair from four thin bars positioned around a zero-size anchor at the middle of the screen.
- Measure the target transform's speed each frame and choose a "moving" or "standing" gap.
- Smoothly lerp the current gap and reposition the four bars every frame.

```csharp
using UnityEngine;
using UnityEngine.UIElements;

public class DynamicCrosshairUI : MonoBehaviour
{
    [SerializeField] private Transform target;
    [SerializeField] private float standingGap = 6f;
    [SerializeField] private float movingGap = 26f;
    [SerializeField] private float barLength = 14f;
    [SerializeField] private float barThickness = 3f;
    [SerializeField] private float moveThreshold = 0.1f;
    [SerializeField] private float smoothing = 12f;

    private VisualElement top, bottom, left, right;
    private Vector3 lastPosition;
    private float gap;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        VisualElement anchor = new VisualElement();
        anchor.pickingMode = PickingMode.Ignore;
        anchor.style.position = Position.Absolute;
        anchor.style.left = Length.Percent(50);
        anchor.style.top = Length.Percent(50);
        anchor.style.width = 0;
        anchor.style.height = 0;
        root.Add(anchor);

        top = MakeBar(anchor);
        bottom = MakeBar(anchor);
        left = MakeBar(anchor);
        right = MakeBar(anchor);

        if (target == null) target = transform;
        lastPosition = target.position;
        gap = standingGap;
        Layout();
    }

    private VisualElement MakeBar(VisualElement parent)
    {
        VisualElement bar = new VisualElement();
        bar.pickingMode = PickingMode.Ignore;
        bar.style.position = Position.Absolute;
        bar.style.backgroundColor = new Color(1f, 1f, 1f, 0.9f);
        parent.Add(bar);
        return bar;
    }

    private void Update()
    {
        Vector3 delta = target.position - lastPosition;
        float speed = new Vector2(delta.x, delta.z).magnitude / Mathf.Max(Time.deltaTime, 0.0001f);
        lastPosition = target.position;

        float goal = speed > moveThreshold ? movingGap : standingGap;
        gap = Mathf.Lerp(gap, goal, 1f - Mathf.Exp(-smoothing * Time.deltaTime));
        Layout();
    }

    private void Layout()
    {
        float half = barThickness * 0.5f;

        top.style.width = barThickness;
        top.style.height = barLength;
        top.style.left = -half;
        top.style.top = -(gap + barLength);

        bottom.style.width = barThickness;
        bottom.style.height = barLength;
        bottom.style.left = -half;
        bottom.style.top = gap;

        left.style.width = barLength;
        left.style.height = barThickness;
        left.style.left = -(gap + barLength);
        left.style.top = -half;

        right.style.width = barLength;
        right.style.height = barThickness;
        right.style.left = gap;
        right.style.top = -half;
    }
}
```

Assign the player (or leave empty to use this object) and the crosshair measures its horizontal speed from frame to frame. The four bars hang off a zero-size anchor at 50%/50% of the screen, so only their pixel offsets from the centre change. An exponential lerp opens the gap while moving and closes it when standing still.

