public class MinimapUI : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private float worldRange = 40f;
    [SerializeField] private float mapSize = 220f;
    [SerializeField] private float dotSize = 10f;

    private VisualElement map;
    private readonly List<VisualElement> dots = new List<VisualElement>();

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.pickingMode = PickingMode.Ignore;

        map = new VisualElement();
        map.style.position = Position.Absolute;
        map.style.right = 30;
        map.style.top = 30;
        map.style.width = mapSize;
        map.style.height = mapSize;
        map.style.backgroundColor = new Color(0.05f, 0.08f, 0.1f, 0.75f);
        map.style.borderTopWidth = 3;
        map.style.borderBottomWidth = 3;
        map.style.borderLeftWidth = 3;
        map.style.borderRightWidth = 3;
        map.style.borderTopColor = Color.white;
        map.style.borderBottomColor = Color.white;
        map.style.borderLeftColor = Color.white;
        map.style.borderRightColor = Color.white;
        map.style.overflow = Overflow.Hidden;
        root.Add(map);

        VisualElement playerDot = CreateDot(Color.green, dotSize + 2f);
        playerDot.style.left = mapSize * 0.5f - (dotSize + 2f) * 0.5f - 3f;
        playerDot.style.top = mapSize * 0.5f - (dotSize + 2f) * 0.5f - 3f;
        map.Add(playerDot);
        dots.Clear();
    }

    private VisualElement CreateDot(Color color, float size)
    {
        VisualElement dot = new VisualElement();
        dot.style.position = Position.Absolute;
        dot.style.width = size;
        dot.style.height = size;
        dot.style.backgroundColor = color;
        dot.style.borderTopLeftRadius = size * 0.5f;
        dot.style.borderTopRightRadius = size * 0.5f;
        dot.style.borderBottomLeftRadius = size * 0.5f;
        dot.style.borderBottomRightRadius = size * 0.5f;
        return dot;
    }

    private void LateUpdate()
    {
        if (player == null) return;

        List<MinimapMarker> markers = MinimapMarker.All;
        while (dots.Count < markers.Count)
        {
            VisualElement dot = CreateDot(Color.white, dotSize);
            map.Add(dot);
            dots.Add(dot);
        }

        float half = mapSize * 0.5f;
        float inner = half - dotSize * 0.5f - 3f;
        for (int i = 0; i < dots.Count; i++)
        {
            if (i >= markers.Count)
            {
                dots[i].style.display = DisplayStyle.None;
                continue;
            }

            Vector3 offset = markers[i].transform.position - player.position;
            Vector2 mapPos = new Vector2(offset.x, -offset.z) / worldRange * half;
            if (mapPos.magnitude > inner) mapPos = mapPos.normalized * inner;

            dots[i].style.display = DisplayStyle.Flex;
            dots[i].style.backgroundColor = markers[i].DotColor;
            dots[i].style.left = half - 3f - dotSize * 0.5f + mapPos.x;
            dots[i].style.top = half - 3f - dotSize * 0.5f + mapPos.y;
        }
    }
}
```

Enemies, pickups and objectives just carry a `MinimapMarker` with a type; they add themselves to a static list when enabled and leave it when disabled or destroyed, so the map never needs a reference to them. The map keeps a pool of dots that is grown when needed, positions each one from its offset to the player (north-up), and pins far-away markers to the border so they still show direction.

