- A Rigidbody2D controller with horizontal acceleration/deceleration, a jump with variable height (releasing the button early cuts the upward speed) and stronger gravity when falling.
- Coyote time lets you still jump for 0.1 s after walking off a ledge, and a jump buffer remembers a jump press made up to 0.12 s before landing.
- Ground is detected with a thin `OverlapBox` just below the collider, ignoring triggers and the player itself.

```csharp
using UnityEngine;

[RequireComponent(typeof(Rigidbody2D), typeof(BoxCollider2D))]
public class PlatformerController2D : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 8f;
    [SerializeField] private float acceleration = 70f;
    [SerializeField] private float deceleration = 90f;
    [SerializeField] private float jumpVelocity = 14f;
    [SerializeField] private float coyoteTime = 0.1f;
    [SerializeField] private float jumpBufferTime = 0.12f;
    [SerializeField] private float fallGravityMultiplier = 2.2f;
    [SerializeField] private float jumpCutMultiplier = 0.5f;
    [SerializeField] private float groundCheckDistance = 0.06f;
    [SerializeField] private LayerMask groundMask = ~0;

    private Rigidbody2D body;
    private BoxCollider2D box;
    private float inputX;
    private float coyoteCounter;
    private float bufferCounter;
    private float baseGravity;

    public bool Grounded { get; private set; }

    private void Awake()
    {
        body = GetComponent<Rigidbody2D>();
        box = GetComponent<BoxCollider2D>();
        body.freezeRotation = true;
        baseGravity = body.gravityScale;
    }

    private void Update()
    {
        inputX = Input.GetAxisRaw("Horizontal");
        Grounded = CheckGround();

        coyoteCounter = Grounded ? coyoteTime : coyoteCounter - Time.deltaTime;
        if (Input.GetButtonDown("Jump")) bufferCounter = jumpBufferTime;
        else bufferCounter -= Time.deltaTime;

        if (bufferCounter > 0f && coyoteCounter > 0f)
        {
            body.velocity = new Vector2(body.velocity.x, jumpVelocity);
            bufferCounter = 0f;
            coyoteCounter = 0f;
        }

        if (Input.GetButtonUp("Jump") && body.velocity.y > 0f)
            body.velocity = new Vector2(body.velocity.x, body.velocity.y * jumpCutMultiplier);
    }

    private void FixedUpdate()
    {
        float target = inputX * moveSpeed;
        float rate = Mathf.Abs(target) > 0.01f ? acceleration : deceleration;
        float vx = Mathf.MoveTowards(body.velocity.x, target, rate * Time.fixedDeltaTime);
        body.velocity = new Vector2(vx, body.velocity.y);
        body.gravityScale = body.velocity.y < -0.1f ? baseGravity * fallGravityMultiplier : baseGravity;
    }

    private bool CheckGround()
    {
        Bounds b = box.bounds;
        Vector2 center = new Vector2(b.center.x, b.min.y - groundCheckDistance * 0.5f);
        Vector2 size = new Vector2(b.size.x * 0.9f, groundCheckDistance);
        foreach (Collider2D hit in Physics2D.OverlapBoxAll(center, size, 0f, groundMask))
        {
            if (hit.isTrigger || hit.gameObject == gameObject) continue;
            return true;
        }
        return false;
    }
}
```

Coyote time and the jump buffer are just two countdown timers. The coyote timer is refilled every frame the player stands on ground, and the buffer timer is refilled on a jump press; a jump happens whenever both are above zero, so a press just before landing and a press just after leaving a ledge both work. The jump cut on release gives short hops for taps and full jumps for held presses.

**Plan**
- `DashAbility` goes on a player with a CharacterController; pressing Q starts a dash if the cooldown is over and the player is not already dashing.
- The dash direction is the current WASD input relative to the player (or forward when no key is held); a coroutine moves the controller `dashDistance` metres over `dashDuration` seconds, so the distance is fixed and walls stop it naturally.
- A UI Toolkit bar at the bottom of the screen shows the cooldown; `OnDashStarted` and `OnDashEnded` events are available for effects.

```csharp
using System;
using System.Collections;
using UnityEngine;
using UnityEngine.UIElements;

[RequireComponent(typeof(CharacterController))]
public class DashAbility : MonoBehaviour
{
    [SerializeField] private KeyCode dashKey = KeyCode.Q;
    [SerializeField] private float dashDistance = 6f;
    [SerializeField] private float dashDuration = 0.15f;
    [SerializeField] private float cooldown = 1.5f;

    private CharacterController controller;
    private float readyTime;
    private VisualElement fill;
    private Label label;

    public bool IsDashing { get; private set; }
    public event Action OnDashStarted;
    public event Action OnDashEnded;

    private void Start()
    {
        controller = GetComponent<CharacterController>();
        BuildUi();
    }

    private void Update()
    {
        if (Input.GetKeyDown(dashKey) && !IsDashing && Time.time >= readyTime) StartCoroutine(Dash());

        float remaining = Mathf.Max(0f, readyTime - Time.time);
        float ready = cooldown > 0f ? 1f - remaining / cooldown : 1f;
        fill.style.width = Length.Percent(ready * 100f);
        label.text = remaining > 0f ? "Dash " + remaining.ToString("0.0") + "s" : "Dash [" + dashKey + "] ready";
    }

    private IEnumerator Dash()
    {
        IsDashing = true;
        readyTime = Time.time + cooldown;

        Vector3 direction = transform.right * Input.GetAxisRaw("Horizontal") + transform.forward * Input.GetAxisRaw("Vertical");
        direction.y = 0f;
        direction = direction.sqrMagnitude > 0.01f ? direction.normalized : transform.forward;

        if (OnDashStarted != null) OnDashStarted();
        float speed = dashDistance / dashDuration;
        float elapsed = 0f;
        while (elapsed < dashDuration)
        {
            float step = Mathf.Min(Time.deltaTime, dashDuration - elapsed);
            controller.Move(direction * speed * step);
            elapsed += step;
            yield return null;
        }

        IsDashing = false;
        if (OnDashEnded != null) OnDashEnded();
    }

    private void BuildUi()
    {
        UIDocument doc = gameObject.AddComponent<UIDocument>();
        PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
        settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
        settings.referenceResolution = new Vector2Int(1920, 1080);
        doc.panelSettings = settings;
        VisualElement root = doc.rootVisualElement;
        root.pickingMode = PickingMode.Ignore;

        VisualElement bar = new VisualElement();
        bar.style.position = Position.Absolute;
        bar.style.bottom = 40;
        bar.style.alignSelf = Align.Center;
        bar.style.width = 360;
        bar.style.height = 36;
        bar.style.backgroundColor = new Color(0.1f, 0.11f, 0.16f, 0.9f);
        fill = new VisualElement();
        fill.style.height = Length.Percent(100f);
        fill.style.backgroundColor = new Color(0.3f, 0.55f, 0.95f);
        bar.Add(fill);
        label = new Label();
        label.style.position = Position.Absolute;
        label.style.width = Length.Percent(100f);
        label.style.unityTextAlign = TextAnchor.MiddleCenter;
        label.style.fontSize = 22;
        label.style.color = Color.white;
        bar.Add(label);
        root.Add(bar);
    }
}
```

Moving by `speed * step` for exactly `dashDuration` seconds covers the same distance at any frame rate, and the last step is shortened so it never overshoots. Because the dash uses `CharacterController.Move`, collisions with walls and slopes work as normal and the player cannot be pushed through geometry. Keep your normal movement script, since this one only adds the burst.

**Plan**
- Mouse movement changes `yaw` and `pitch` (pitch clamped), and the scroll wheel zooms between a minimum and maximum distance.
- Each frame the camera aims at a pivot above the target and sphere-casts from the pivot backwards along the camera direction; the nearest hit that is not part of the target shortens the allowed distance.
- The camera moves in instantly when blocked (so it never shows the inside of a wall) and eases back out smoothly once the way is clear.

```csharp
using UnityEngine;

public class OrbitCamera : MonoBehaviour
{
    [SerializeField] private Transform target;
    [SerializeField] private Vector3 pivotOffset = new Vector3(0f, 1.6f, 0f);
    [SerializeField] private float distance = 5f;
    [SerializeField] private float minDistance = 1.5f;
    [SerializeField] private float maxDistance = 9f;
    [SerializeField] private float sensitivity = 3f;
    [SerializeField] private float minPitch = -30f;
    [SerializeField] private float maxPitch = 70f;
    [SerializeField] private float collisionRadius = 0.3f;
    [SerializeField] private LayerMask collisionMask = ~0;
    [SerializeField] private float recoverSpeed = 8f;

    private float yaw;
    private float pitch = 15f;
    private float currentDistance;

    public Quaternion PlanarRotation { get { return Quaternion.Euler(0f, yaw, 0f); } }

    private void Start()
    {
        if (target == null)
        {
            GameObject player = GameObject.FindWithTag("Player");
            if (player != null) target = player.transform;
        }
        currentDistance = distance;
        Vector3 angles = transform.eulerAngles;
        yaw = angles.y;
        Cursor.lockState = CursorLockMode.Locked;
        Cursor.visible = false;
    }

    private void LateUpdate()
    {
        if (target == null) return;

        if (Input.GetKeyDown(KeyCode.Escape))
        {
            Cursor.lockState = CursorLockMode.None;
            Cursor.visible = true;
        }
        if (Cursor.lockState == CursorLockMode.Locked)
        {
            yaw += Input.GetAxis("Mouse X") * sensitivity;
            pitch = Mathf.Clamp(pitch - Input.GetAxis("Mouse Y") * sensitivity, minPitch, maxPitch);
        }
        distance = Mathf.Clamp(distance - Input.mouseScrollDelta.y * 0.5f, minDistance, maxDistance);

        Vector3 pivot = target.position + pivotOffset;
        Quaternion rotation = Quaternion.Euler(pitch, yaw, 0f);
        Vector3 backwards = rotation * Vector3.back;

        float allowed = distance;
        RaycastHit[] hits = Physics.SphereCastAll(pivot, collisionRadius, backwards, distance, collisionMask, QueryTriggerInteraction.Ignore);
        foreach (RaycastHit hit in hits)
        {
            if (hit.transform.IsChildOf(target) || hit.distance <= 0f) continue;
            allowed = Mathf.Min(allowed, hit.distance);
        }

        currentDistance = allowed < currentDistance
            ? allowed
            : Mathf.Lerp(currentDistance, allowed, 1f - Mathf.Exp(-recoverSpeed * Time.deltaTime));
        transform.position = pivot + backwards * Mathf.Max(currentDistance, 0.2f);
        transform.rotation = rotation;
    }
}
```

Running in `LateUpdate` means the camera follows the player after all movement for the frame has been applied, which avoids jitter. Sphere casting with a radius (instead of a ray) keeps the camera's near plane out of the wall, hits on the player's own colliders are skipped, and the asymmetric smoothing (snap in, ease out) is what keeps walls from ever flashing into view. `PlanarRotation` lets a movement script move relative to the camera.

**Plan**
- The script reads the Animator's parameter list once and sets only the ones that exist (`Speed` float, `Grounded` bool, `Jump` trigger), so a controller missing one of them does not spam warnings.
- Speed is measured from how far the transform actually moved, normalised by `maxSpeed` to 0-1 and passed to `SetFloat` with damping, so it works with a CharacterController, Rigidbody or any other movement.
- Grounded comes from a short downward raycast (or the CharacterController); the Jump trigger fires on the frame the character leaves the ground while moving upward.

```csharp
using System;
using UnityEngine;

[RequireComponent(typeof(Animator))]
public class AnimatorDriver : MonoBehaviour
{
    [SerializeField] private float maxSpeed = 8f;
    [SerializeField] private float speedDamping = 0.1f;
    [SerializeField] private float groundCheckDistance = 0.2f;
    [SerializeField] private float jumpVelocityThreshold = 2f;
    [SerializeField] private LayerMask groundMask = ~0;

    private static readonly int SpeedHash = Animator.StringToHash("Speed");
    private static readonly int GroundedHash = Animator.StringToHash("Grounded");
    private static readonly int JumpHash = Animator.StringToHash("Jump");

    private Animator animator;
    private CharacterController controller;
    private Vector3 lastPosition;
    private bool wasGrounded = true;
    private bool hasSpeed;
    private bool hasGrounded;
    private bool hasJump;

    public event Action OnLanded;

    private void Awake()
    {
        animator = GetComponent<Animator>();
        controller = GetComponentInParent<CharacterController>();
        foreach (AnimatorControllerParameter parameter in animator.parameters)
        {
            if (parameter.nameHash == SpeedHash) hasSpeed = true;
            else if (parameter.nameHash == GroundedHash) hasGrounded = true;
            else if (parameter.nameHash == JumpHash) hasJump = true;
        }
        lastPosition = transform.position;
    }

    private void Update()
    {
        float dt = Time.deltaTime;
        if (dt <= 0f) return;

        Vector3 delta = transform.position - lastPosition;
        lastPosition = transform.position;
        float horizontalSpeed = new Vector3(delta.x, 0f, delta.z).magnitude / dt;
        float verticalVelocity = delta.y / dt;
        bool grounded = IsGrounded();

        if (hasSpeed) animator.SetFloat(SpeedHash, Mathf.Clamp01(horizontalSpeed / maxSpeed), speedDamping, dt);
        if (hasGrounded) animator.SetBool(GroundedHash, grounded);
        if (hasJump && wasGrounded && !grounded && verticalVelocity > jumpVelocityThreshold) animator.SetTrigger(JumpHash);
        if (!wasGrounded && grounded && OnLanded != null) OnLanded();
        wasGrounded = grounded;
    }

    private bool IsGrounded()
    {
        Vector3 origin = transform.position + Vector3.up * 0.1f;
        if (Physics.Raycast(origin, Vector3.down, groundCheckDistance + 0.1f, groundMask, QueryTriggerInteraction.Ignore)) return true;
        return controller != null && controller.isGrounded;
    }
}
```

Place it on the object with the Animator and create parameters named `Speed` (Float), `Grounded` (Bool) and `Jump` (Trigger) in the Animator Controller. Deriving speed from real displacement means the animation matches what the character is actually doing, even when it is blocked by a wall or pushed by a platform, and the jump trigger is only raised when the character left the ground with upward velocity, so walking off a ledge plays the fall animation rather than a jump.

**Plan**
- A self-contained 2D controller: run with acceleration, ground jump, and wall detection with two thin `OverlapBox` checks on the left and right sides of the collider (only while airborne).
- Pressing jump while touching a wall sets the velocity to a fixed push away from the wall (`wallJumpVelocity`), and horizontal input is ignored for 0.2 s so the player is not pulled straight back into it.
- Pressing toward a wall while falling makes the player slide down slowly (`wallSlideSpeed`).

```csharp
using UnityEngine;

[RequireComponent(typeof(Rigidbody2D), typeof(BoxCollider2D))]
public class WallJumpController2D : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 7f;
    [SerializeField] private float acceleration = 80f;
    [SerializeField] private float jumpVelocity = 13f;
    [SerializeField] private Vector2 wallJumpVelocity = new Vector2(9f, 13f);
    [SerializeField] private float wallSlideSpeed = 2.5f;
    [SerializeField] private float controlLockTime = 0.2f;
    [SerializeField] private float checkDistance = 0.08f;
    [SerializeField] private LayerMask solidMask = ~0;

    private Rigidbody2D body;
    private BoxCollider2D box;
    private float inputX;
    private float lockTimer;
    private bool grounded;
    private int wallDirection;

    private void Awake()
    {
        body = GetComponent<Rigidbody2D>();
        box = GetComponent<BoxCollider2D>();
        body.freezeRotation = true;
    }

    private void Update()
    {
        inputX = Input.GetAxisRaw("Horizontal");
        lockTimer -= Time.deltaTime;

        Bounds b = box.bounds;
        grounded = Overlaps(new Vector2(b.center.x, b.min.y - checkDistance * 0.5f), new Vector2(b.size.x * 0.9f, checkDistance));
        wallDirection = grounded ? 0 : DetectWall(b);

        if (!Input.GetButtonDown("Jump")) return;
        if (grounded)
        {
            body.velocity = new Vector2(body.velocity.x, jumpVelocity);
        }
        else if (wallDirection != 0)
        {
            body.velocity = new Vector2(-wallDirection * wallJumpVelocity.x, wallJumpVelocity.y);
            lockTimer = controlLockTime;
        }
    }

    private void FixedUpdate()
    {
        Vector2 velocity = body.velocity;
        if (lockTimer <= 0f)
            velocity.x = Mathf.MoveTowards(velocity.x, inputX * moveSpeed, acceleration * Time.fixedDeltaTime);

        bool pushingIntoWall = wallDirection != 0 && Mathf.Approximately(Mathf.Sign(inputX), wallDirection) && inputX != 0f;
        if (pushingIntoWall && velocity.y < -wallSlideSpeed) velocity.y = -wallSlideSpeed;
        body.velocity = velocity;
    }

    private int DetectWall(Bounds b)
    {
        Vector2 size = new Vector2(checkDistance, b.size.y * 0.8f);
        float offset = b.extents.x + checkDistance * 0.5f;
        if (Overlaps(new Vector2(b.center.x + offset, b.center.y), size)) return 1;
        if (Overlaps(new Vector2(b.center.x - offset, b.center.y), size)) return -1;
        return 0;
    }

    private bool Overlaps(Vector2 center, Vector2 size)
    {
        foreach (Collider2D hit in Physics2D.OverlapBoxAll(center, size, 0f, solidMask))
        {
            if (!hit.isTrigger && hit.gameObject != gameObject) return true;
        }
        return false;
    }
}
```

`wallDirection` is +1 when the wall is on the right and -1 on the left, so the wall jump sets horizontal velocity to `-wallDirection * x`, which always points away from the wall. The 0.2 s control lock is what makes the jump feel like a real kick-off: without it, the player holding toward the wall would immediately cancel the push. Wall checks are skipped while grounded so floors never count as walls.

